// Generated data file: base64-encoded theme icon images.
// Kept separate from script.js so the actual logic stays readable.
//
// Embedding these as data URIs (instead of linking the .png files directly)
// avoids a Chrome quirk where drawing a file:// image onto a <canvas> marks
// it 'tainted', which silently breaks the PNG export when this page is
// opened by double-clicking it instead of via a web server.
//
// TRADE-OFF: swapping an icon now means asking Claude to regenerate this
// file from the new image (same filenames below), rather than just
// overwriting the .png file and refreshing.
const THEME_IMAGES = {
  '來義鄉排灣族': 'data:image/png;base64,',
  '佛': 'data:image/png;base64,',
  '道': 'data:image/png;base64,'
};
